class RobotPet:
    def __init__(self, name, battery=100, mood="neutral"):
        self.name = name
        self.battery = battery
        self.mood = mood

    def speak(self):
        if self.battery < 30:
            return f"{self.name} mumbles: I need a recharge."
        if self.mood == "happy":
            return f"{self.name} says: I am so happy to see you!"
        return f"Hello, I am {self.name}."


class RobotCat(RobotPet):
    def speak(self):
        if self.battery < 30:
            return f"{self.name} is too tired to purr."
        if self.mood == "happy":
            return f"{self.name} is one happy kitty!"
        return f"Meow! I am {self.name}."


class RobotBird(RobotPet):
    def speak(self):
        if self.battery < 30:
            return f"{self.name} peeps: my battery is low."
        if self.mood == "happy":
            return f"{self.name} sings a lovely song!"
        return f"Chirp! I am {self.name}."


class RobotDog(RobotPet):
    def speak(self):
        if self.battery < 30:
            return f"{self.name} whines: I need to charge."
        if self.mood == "happy":
            return f"Best day ever, barks {self.name}!"
        return f"Woof! I am {self.name}."


if __name__ == "__main__":
    pets = [RobotPet("Robo"), RobotCat("Whiskers"),
            RobotBird("Tweety"), RobotDog("Rex")]
    for pet in pets:
        pet.battery = 50
        pet.mood = "neutral"
        print(pet.speak())
        pet.mood = "happy"
        print(pet.speak())
        pet.battery = 10
        print(pet.speak())
